import sys; sys.path.insert(0, '/home/user/Possession-Taxonomy/rebuild/work/F3/agent')
from hb import *
HUB = WP + "Inter-service_awards_and_decorations_of_the_United_States_military"
dec = K("US gallantry and merit decoration", "United States military decoration for valour, wounds or meritorious service.", HUB, a="US valor award · personal decoration",
  t=["named or unnamed", "with oak leaf clusters or stars", "'V' device", "ribbon bar", "miniature"],
  x=[X("Medal of Honor", "The highest US military decoration for valour, in separate Army, Navy and Air Force versions.", WP + "Medal_of_Honor", y="1861", a="MOH · Congressional Medal of Honor",
       v=[("Navy Medal of Honor", "", "1861", "Philadelphia Mint design"), ("Army Medal of Honor", "William Wilson and Son", "1862", ""),
          ("Army 1904 redesign", "", "1904", "Gillespie; patented"), ("Navy 'Tiffany Cross'", "Tiffany & Co.", "1919–1942", "combat version"),
          ("Neck-ribbon versions", "", "1944", "light-blue neck ribbon"), ("Air Force Medal of Honor", "", "1965", "first awarded 1967")],
       dt="service version · suspension type · posthumous"),
     X("Distinguished Service Cross", "Army bronze cross 'For Valor', second only to the Medal of Honor.", WP + "Distinguished_Service_Cross_(United_States)", y="1918", a="DSC",
       v=[("First type", "", "1918", "Embury and Smith; Cecere; 100 struck"), ("Second (current) type", "", "1918", "Sinnock model; eagle")], dt="named · oak leaf clusters"),
     X("Navy Cross", "Navy and Marine Corps cross for combat heroism, below the Medal of Honor since 1942.", WP + "Navy_Cross", y="1919",
       v=[("Navy Cross", "", "1919", "James Earle Fraser; caravel"), ("Combat-only Navy Cross", "", "1942", "")], dt="gold stars for further awards"),
     X("Silver Star", "Third-highest US valour decoration, with the original Citation Star at its centre.", WP + "Silver_Star", y="1932",
       v=[("Citation Star", "", "1918", "ribbon device, predecessor"), ("Silver Star Medal", "", "1932", "")], dt="oak leaf clusters or stars"),
     X("Legion of Merit", "Decoration for exceptionally meritorious conduct, in four degrees for foreign recipients.", WP + "Legion_of_Merit", y="1942",
       v=[("Chief Commander", "", "1942", "breast star"), ("Commander", "", "1942", "neck badge"), ("Officer", "", "1942", ""), ("Legionnaire", "", "1942", "and US awards")]),
     X("Bronze Star Medal", "Decoration for lesser heroism or merit in combat zones.", WP + "Bronze_Star_Medal", y="1944",
       v=[("Bronze Star Medal", "Bailey Banks & Biddle", "1944", "Rudolf Freund design"), ("With 'V' device", "", "", "valour")], dt="'V' device · oak leaf clusters or stars"),
     X("Purple Heart", "Medal for those wounded or killed by enemy action, revived from Washington's Badge of Military Merit.", WP + "Purple_Heart", y="1932",
       v=[("Badge of Military Merit", "", "1782", "three awarded"), ("Purple Heart", "", "1932", "Elizabeth Will design, Sinnock model"),
          ("WWII stock", "", "1940s", "about 1.5 million made for the planned invasion of Japan")], dt="engraved or unnamed · oak leaf clusters")],
  m=[["Air Force Cross", ""], ["Coast Guard Cross", ""], ["Distinguished Flying Cross", ""], ["Meritorious Service Medal", ""], ["Air Medal", ""]])
camp = K("US campaign and service medal", "United States medal for service in a campaign, war or theatre, or for good conduct.", HUB, a="campaign medal · service medal",
  t=["campaign stars", "battle and service clasps", "ribbon bar"],
  x=[X("Civil War Campaign Medal", "First US campaign medal, issued retroactively for Civil War service.", WP + "Civil_War_Campaign_Medal", y="1907",
       v=[("Army version", "", "1907", "Lincoln obverse"), ("Navy and Marine Corps version", "", "1908", "Monitor and Virginia")], dt="Francis D. Millet design · blue and grey ribbon"),
     X("World War I Victory Medal", "US service medal for the First World War with battle and service clasps.", WP + "World_War_I_Victory_Medal_(United_States)", y="1919",
       v=[("Army battle clasps", "", "", "Aisne, Meuse-Argonne, St. Mihiel, Somme-Offensive"), ("Defensive Sector clasp", "", "", ""),
          ("Army service clasps", "", "", "England, France, Italy, Russia, Siberia"), ("Navy operational clasps", "", "", "Armed Guard, Submarine, Transport, Mine Sweeping")],
       dt="James Earle Fraser design · clasp combinations · Citation Star"),
     X("Second World War theatre medals", "Three US campaign medals for the American, Asiatic–Pacific and European–African–Middle Eastern theatres, sharing Weinman's eagle reverse.",
       WP + "American_Campaign_Medal", y="1942",
       v=[("American Campaign Medal", "", "1942", "Thomas Hudson Jones obverse"), ("Asiatic–Pacific Campaign Medal", "", "1942", ""),
          ("European–African–Middle Eastern Campaign Medal", "", "1942", "")], dt="service stars"),
     X("Vietnam Service Medal", "US medal for service in and around Vietnam, 1965–1973.", WP + "Vietnam_Service_Medal", y="1965",
       v=[("Vietnam Service Medal", "", "1965", "17 campaigns"), ("Operation Frequent Wind star", "", "1975", "Navy, Marine Corps, Air Force")], dt="campaign stars"),
     X("Good Conduct Medal", "Service medal for three years of honourable enlisted service, with a version for each service.", WP + "Good_Conduct_Medal_(United_States)", y="1869",
       v=[("Navy", "", "1869", "four versions"), ("Marine Corps", "", "1896", ""), ("Coast Guard", "", "1923", ""), ("Army", "", "1941", "clasps with loops"),
          ("Air Force", "", "1963", ""), ("Space Force", "", "2023", "")], dt="service · clasps, stars or oak leaf clusters")],
  m=[["National Defense Service Medal", ""], ["Armed Forces Expeditionary Medal", ""], ["Korean Service Medal", ""], ["Southwest Asia Service Medal", ""],
     ["Afghanistan Campaign Medal", ""], ["Iraq Campaign Medal", ""], ["Global War on Terrorism Service Medal", ""]])
save("06_01", [dec, camp], [], [],
 "Both kinds new, sourced to the Wikipedia inter-service awards page; archetypes from retrieved Wikipedia articles. Other decorations and later campaign medals listed on the hub page are kept as flat entries without archetypes. "
 "Issuer is the US government, so archetype mk left empty; Tiffany & Co., William Wilson and Son and Bailey Banks & Biddle appear only as version makers. Institute of Heraldry pages not retrieved.")
